import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import {fileURLToPath} from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');const files=[];const walk=d=>{for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);if(e.isDirectory())walk(p);else if(/\.(js|mjs)$/.test(e.name))files.push(p);}};walk(path.join(root,'src'));walk(path.join(root,'api'));walk(path.join(root,'scripts'));
test('SEPA-X has zero runtime imports from frozen RC2 namespace',()=>{for(const f of files){const s=fs.readFileSync(f,'utf8');assert.equal(/from\s+['"][^'"]*tfe-v20|import\s*\([^)]*tfe-v20/i.test(s),false,`RC2 import in ${f}`);}});
test('SEPA-X never grants execution permission',async()=>{const {DEFAULT_CONFIG}=await import('../src/config.js');assert.equal(DEFAULT_CONFIG.permissions.executionAllowed,false);assert.equal(DEFAULT_CONFIG.permissions.automaticOrders,false);});
